def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

function arraySum(numbers) {
    return numbers.reduce((sum, number) => sum + number, 0);
}

def find_largest(numbers):
    if not numbers:
        return None
    return max(numbers)

